baseline.sql:
WITH race AS (
  SELECT raceId FROM races WHERE year = 1957 AND name = 'British Grand Prix'
), participation AS (
  SELECT r.driverId,
         CASE WHEN r.position IS NOT NULL THEN 1 ELSE 0 END AS classified_finisher
  FROM results r
  JOIN race ON race.raceId = r.raceId
)
SELECT ROUND(100.0 * SUM(classified_finisher) / COUNT(*), 2) AS percentage_classified_finishers
FROM participation;

treatment.sql:
WITH race AS (
  SELECT raceId FROM races WHERE year = 1957 AND name = 'British Grand Prix'
), race_entries AS (
  SELECT r.positionText, s.status
  FROM results r
  JOIN race x ON x.raceId = r.raceId
  JOIN status s ON s.statusId = r.statusId
)
SELECT ROUND(100.0 * SUM(CASE WHEN status = 'Finished' OR status GLOB '+*' THEN 1 ELSE 0 END) / COUNT(*), 2) AS classified_finisher_percentage
FROM race_entries;

